import { currentJob,jobEditor,JOB_LABELS,jobDifferences,submissionJob,candidateJobProjection } from './job-settings.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function jobDescriptionView(job){const c=job.content;return `<div class="job-description"><span class="pill quiet">${job.legacy?'旧デモの保存範囲':'求人説明 v'+job.version}</span><h3>${esc(c.title)}</h3>${job.legacy?'<p>旧デモの提出物に残る説明のみ確認できます。次の工程・回答窓口の当時の表示は保存されていません。</p><p>'+esc(job.legacyScenario)+'</p>':'<div class="job-scenes">'+c.scenes.map(s=>'<section><h4>'+esc(s.title)+'</h4><p>'+esc(s.description)+'</p></section>').join('')+'</div><dl><dt>次の工程</dt><dd>'+esc(c.nextStep)+'</dd><dt>回答窓口</dt><dd>'+esc(c.contact)+'</dd></dl>'}${c.changeReason?'<p><strong>変更理由</strong><br>'+esc(c.changeReason)+'</p>':''}${c.followupQuestion?'<p><strong>追加で聞きたい1問（回答は任意）</strong><br>'+esc(c.followupQuestion)+'</p>':''}</div>`;}
export function jobDiffView(before,after){if(before.legacy)return '<p class="small">旧デモでは求人全体の版を保存していなかったため、完全な項目差分は復元できません。提出物に残る説明と現在の公開内容をそれぞれ確認できます。</p><details><summary>旧提出時に保存された説明</summary>'+jobDescriptionView(before)+'</details><details open><summary>現在の公開内容</summary>'+jobDescriptionView(after)+'</details>';const changes=jobDifferences(before.content,after.content);return changes.length?changes.map(d=>'<section class="diff"><h4>'+esc(d.label)+'</h4><div><span>提出時の求人説明 v'+before.version+'</span><p>'+esc(d.before||'記載なし')+'</p></div><div class="after"><span>現在の求人説明 v'+after.version+'</span><p>'+esc(d.after||'記載なし')+'</p></div></section>').join(''):'<p>説明本文の差分はありません。</p>';}
const RESPONSE_LABELS={continue:'今の経験で進む',add:'経験を追加する',question:'質問する'};
export function candidateJobView(state){const job=candidateJobProjection(state),entry=state.submissions.at(-1),old=entry&&submissionJob(state,entry.version);let result='<section class="card candidate-job"><details><summary>企業が提示している仕事の説明 · 求人 v'+job.version+'</summary>'+jobDescriptionView(job)+'</details><p class="small">灯りワークスの架空求人です。企業の仕事内容と、候補者本人の経験の自己申告は区別します。適性の採点は行いません。</p>';if(old&&old.version!==job.version){const selected=state.jobResponses?.[job.version]?.choice;result+='<div class="job-change"><h2>提出後に仕事の説明が更新されました</h2><p>経験・提出物・これまでの回答はそのまま残っています。追加経験は必須ではありません。未選択でも不足扱いにはしません。</p><details open><summary>提出時と現在の違いを確認</summary>'+jobDiffView(old,job)+'</details><div class="job-response-options">'+Object.entries(RESPONSE_LABELS).map(([key,label])=>'<button class="button '+(selected===key?'':'secondary')+'" data-action="job-response" data-choice="'+key+'" aria-pressed="'+(selected===key)+'">'+label+'</button>').join('')+'</div><p class="small">'+(selected?'求人説明への現在の選択：'+RESPONSE_LABELS[selected]+'。後から変えられます。':'どの選択も任意です。')+'回答を待つ／話を進めるなどの選択は別に保持されます。「質問する」だけでは質問を企業へ共有しません。</p></div>';}return result+'</section>';}
export function submittedJobView(state,entry){const job=submissionJob(state,entry.version);return job?'<details class="submitted-job"><summary>この提出時の仕事の説明を確認</summary>'+jobDescriptionView(job)+'</details>':'';}
function input(key,value,sceneId){const id='job-'+(sceneId?sceneId+'-':'')+key;return '<label class="field" for="'+id+'"><span>'+esc(sceneId?(key==='title'?'場面の見出し':'具体的な仕事内容'):JOB_LABELS[key])+'</span><textarea id="'+id+'" data-job-field="'+key+'" '+(sceneId?'data-job-scene="'+sceneId+'"':'')+' rows="'+(key==='title'?2:3)+'" maxlength="4000">'+esc(value)+'</textarea></label>';}
export function companySettingsView(state,role='recruiter'){const job=currentJob(state),j=state.companyJob;const nav='<section class="page-heading"><span class="eyebrow">会社の役割切替デモ</span><h1>仕事の説明を、同じ前提に。</h1><p>採用担当 B と現場担当 C は操作体験用の役割です。本番の認証・権限管理ではありません。内部提案は公開操作まで候補者に表示されません。</p><div class="actions"><a class="button secondary" href="#company/recruiter">採用担当 B</a><a class="button secondary" href="#company/field">現場担当 C</a><button class="text-link" data-action="to-candidate">候補者の表示へ</button></div></section>';
 if(role==='field'){const p=j.fieldProposal;return nav+'<section class="card job-settings"><h2>現場担当 C：変更の内部提案</h2><p>仕事内容の見直しについて、理由と次に聞きたい1問を採用担当へ渡します。保存しても求人説明や候補者向け質問は変わりません。</p><label class="field" for="field-reason"><span>変更理由（社内提案）</span><textarea id="field-reason" data-field-proposal="reason" maxlength="4000" rows="4">'+esc(j.fieldEditor.reason)+'</textarea></label><label class="field" for="field-question"><span>追加で聞きたい1問（社内提案）</span><textarea id="field-question" data-field-proposal="question" maxlength="4000" rows="3">'+esc(j.fieldEditor.question)+'</textarea></label><button class="button" data-action="save-field-proposal">採用担当 B への内部提案を保存</button>'+(p?'<div class="question-internal"><h3>保存した内部提案 '+p.id+'</h3><p>'+esc(p.reason)+'</p><p>'+esc(p.question)+'</p><p class="small">'+(p.reviewedAt?'採用担当が取り込んだ内容を公開済み':'採用担当の確認待ち。候補者には未公開')+'</p></div>':'')+'</section><details class="card"><summary>現在の候補者向け公開内容</summary>'+jobDescriptionView(job)+'</details>';}
 const draft=jobEditor(state),p=j.fieldProposal;return nav+'<div class="job-settings-grid"><section class="card job-settings"><span class="pill quiet">公開中 v'+job.version+' ／ 編集下書き</span><h2>採用担当 B：公開前に確認する</h2><p>入力・下書き保存では候補者向け説明は変わりません。保存 → 候補者表示のプレビュー → 明示公開の順で更新します。</p>'+(p?'<section class="question-internal"><h3>現場担当 C の内部提案 '+p.id+'</h3><p>理由：'+esc(p.reason)+'</p><p>追加の1問：'+esc(p.question)+'</p><button class="button secondary" data-action="apply-field-proposal" '+(p.baseVersion!==job.version?'disabled':'')+'>確認して公開用の下書きへ取り込む</button><p class="small">取り込むと下の公開用の変更理由・追加質問に転記します。公開前に編集・削除できます。自動公開はしません。</p></section>':'')+(j.recoveredDraft?'<section class="stale-banner"><h3>このタブの編集入力を保管しています</h3><p>公開版または別タブの下書きが変わりました。保管した入力はまだ公開していません。戻すと現在の編集下書きを置き換えます。内容を照合し、保存と再プレビューをしてください。</p><details><summary>保管した入力を見る</summary>'+jobDescriptionView({version:j.recoveredDraft.baseVersion,content:j.recoveredDraft.content})+'</details><button class="button secondary" data-action="recover-job-draft">保管した入力を編集下書きへ戻す</button></section>':'')+input('title',draft.content.title)+draft.content.scenes.map(s=>'<fieldset><legend>仕事の場面</legend>'+input('title',s.title,s.id)+input('description',s.description,s.id)+'</fieldset>').join('')+['nextStep','contact','changeReason','followupQuestion'].map(k=>input(k,draft.content[k])).join('')+'<div class="actions"><button class="button secondary" data-action="save-job-draft">編集内容を下書き保存</button><button class="button" data-action="preview-job">候補者表示をプレビュー</button></div><p id="job-save-status" class="small">'+(j.savedDraft?'下書きの保存記録があります。保存後に編集した場合はもう一度保存してください。':'まだ下書き保存していません。')+'</p></section><aside class="card"><h2>現在の候補者向け公開内容</h2>'+jobDescriptionView(job)+'<p class="small">候補者の旧提出物・回答は公開後も書き換えません。実通知は送りません。</p></aside></div>';
}
